/**
 * Synthetic seed data. Every name and email is invented (emails use the reserved
 * example.com domain) and every image is generated by lib/png.ts.
 */
import type { SamplePattern } from './lib/png.js';
import type { QuoteTerms } from './modules/quotes/quote.js';
import type { RequestStatus } from './modules/requests/request-status.js';
import type { CreateRequestInput } from './modules/requests/requests.schemas.js';

export const SEED_ARTISTS = [
  { name: 'Mara Quintero', bio: 'Fine line and botanical blackwork.', specialties: ['fine_line', 'blackwork', 'geometric'] },
  { name: 'Diego Salas', bio: 'Bold traditional and Japanese-inspired pieces.', specialties: ['traditional', 'neo_traditional', 'japanese'] },
  { name: 'Lu Ortega', bio: 'Black & grey realism and portraits.', specialties: ['realism', 'lettering'] },
] as const;

export type SeedArtistName = (typeof SEED_ARTISTS)[number]['name'];

export type SeedStep =
  | { kind: 'artist'; artist: SeedArtistName; hours: number; body: string; quote?: Partial<QuoteTerms> & Pick<QuoteTerms, 'priceType' | 'amountMinCents'>; images?: SamplePattern[] }
  | { kind: 'client'; hours: number; body: string; images?: SamplePattern[] }
  | { kind: 'status'; artist: SeedArtistName; hours: number; to: RequestStatus; note?: string };

export interface SeedRequest {
  /** Days before "today" the request was submitted. */
  daysAgo: number;
  input: Omit<CreateRequestInput, 'preferredArtistId'> & { preferredArtist?: SeedArtistName };
  images: SamplePattern[];
  steps: SeedStep[];
  /** Expected final status, checked by the seed so the data never drifts from the rules. */
  expect: RequestStatus;
}

